page(2,N,T,big("¿CUÁNTO ES GRAVE?",124,nowrap=True)+f'<div style="display:flex;flex-direction:column;gap:22px">{row("Leve","5,0–5,9 mEq/L")}{row("Moderada","6,0–6,4 mEq/L")}<div style="border-top:4px solid {K};padding-top:22px;display:flex;justify-content:space-between;gap:32px;font-size:40px;color:{R}"><div style="font-weight:800">Grave</div><div style="font-weight:800;text-align:right">≥ 6,5 mEq/L</div></div></div>'+f'<div style="border-top:4px solid {K};padding-top:28px;font-size:42px;font-weight:800;line-height:1.3">O con repercusión en el ECG</div>'),
