page(4,N,T,kicker("PASO 2 · DESPLAZA")+big("INSULINA + GLUCOSA",110,R,True)+'<div style="font-size:50px;font-weight:800;line-height:1.2">10 UI de insulina rápida + 25–50 g de glucosa</div>'+f'<div style="display:flex;flex-direction:column;gap:22px">{row("Glucosado al 10 %","250–500 ml")}{row("Glucosado al 20 %","125–250 ml")}{row("Glucosado al 50 %","50–100 ml")}</div>'+f'<div style="font-size:36px;line-height:1.4;color:{G}">Individualiza la dosis. En estado de hipervolemia, misma glucosa en menos volumen. Insulina sola si la glucemia es &gt; 250 mg/dl.</div>'),
page(5,N,T,kicker("PASO 2 · SUMA")+big("SALBUTAMOL",150,R,True)+'<div style="font-size:48px;font-weight:800;line-height:1.2">10–20 mg nebulizado en 10 min</div>'+f'<div style="border-top:4px solid {K};padding-top:32px;display:flex;flex-direction:column;gap:24px">{big("BICARBONATO",110)}<div style="font-size:48px;font-weight:800;line-height:1.2">Solo si hay acidosis metabólica</div>{row("Bicarbonato 1 M","50–100 mEq IV")}</div>'+f'<div style="font-size:34px;line-height:1.4;color:{G}">No lo mezcles con el calcio en la misma vía: precipita.</div>'),
page(6,N,T,kicker("PASO 3 · ELIMINA")+big("SACA EL POTASIO",128,nowrap=True)+f'<div style="display:flex;flex-direction:column;gap:22px">{line("Diuréticos de asa (furosemida), si la función renal lo permite")}{line("Captores digestivos (patiromer o ciclosilicato de sodio y zirconio)")}{line("Hemodiálisis: de elección en la emergencia, sobre todo en pacientes en diálisis",True)}</div>'+f'<div style="font-size:36px;line-height:1.4;color:{G}">Solo desplazar y eliminar reducen la potasemia.</div>'),
page(7,N,T,ficha_body("HIPERPOTASEMIA","Adulto",[("GRAVE","K ≥ 6,5 mEq/L o repercusión en el ECG"),("1. PROTEGE","Gluconato cálcico 10 %, 1 ampolla (10 ml) IV en 2–3 min. Repetir si persiste el ECG alterado",True),("2. DESPLAZA","Insulina rápida 10 UI + glucosa 25–50 g (250–500 ml al 10 %). Menos volumen al 20 o al 50 % si hay hipervolemia"),("Y SUMA","Salbutamol nebulizado 10–20 mg"),("SI ACIDOSIS","Bicarbonato 1 M, 50–100 mEq IV. No mezclar con el calcio"),("3. ELIMINA","Diurético de asa (furosemida), captores digestivos (patiromer, ciclosilicato), hemodiálisis")],"Ortiz A, et al. Nefrología 2023;43(5):765-82 (consenso SEN, SEMES, SEEN, SEMI y SEC)",size=112),ficha="02"),
